import '../core/jalali.dart';import '../core/persian.dart';import '../domain/task.dart';import '../occasions/holidays.dart';import '../occasions/occasion_rule.dart';
class CalendarScreen extends StatefulWidget{final List<Task> tasks;final ValueChanged<OccasionRule> onReminder;const CalendarScreen({required this.tasks,required this.onReminder,Key? key}):super(key:key);@override State<CalendarScreen> createState()=>_CalendarScreenState();}
class _CalendarScreenState extends State<CalendarScreen>{late Jalali month=Jalali.fromGregorian(DateTime.now());int? selected;@override Widget build(BuildContext context){final first=Jalali(month.year,month.month,1);final offset=(first.weekdayIndex+1)%7;final days=Jalali.daysInMonth(month.year,month.month);final occ=occasions(month.year);final chosen=selected??Jalali.fromGregorian(DateTime.now()).day;final rules=occ.where((o)=>o.month==month.month&&o.day==chosen).toList();final tasks=widget.tasks.where((t)=>t.jalaliDue.year==month.year&&t.jalaliDue.month==month.month&&t.jalaliDue.day==chosen).toList();return Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[IconButton(onPressed:()=>setState(()=>month=month.month==1?Jalali(month.year-1,12,1):Jalali(month.year,month.month-1,1)),icon:const Icon(Icons.chevron_left)),Text('${Jalali.monthNames[month.month-1]} ${fa('${month.year}')}'),IconButton(onPressed:()=>setState(()=>month=month.month==12?Jalali(month.year+1,1,1):Jalali(month.year,month.month+1,1)),icon:const Icon(Icons.chevron_right))]),const Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[Text('ش'),Text('ی'),Text('د'),Text('س'),Text('چ'),Text('پ'),Text('ج')]),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:7,childAspectRatio:1.2),itemCount:offset+days,itemBuilder:(c,i){if(i<offset)return const SizedBox();final d=i-offset+1;final holiday=occ.any((o)=>o.month==month.month&&o.day==d&&o.isHoliday);final hasOcc=occ.any((o)=>o.month==month.month&&o.day==d);final hasTask=widget.tasks.any((t)=>t.jalaliDue.year==month.year&&t.jalaliDue.month==month.month&&t.jalaliDue.day==d);return InkWell(onTap:()=>setState(()=>selected=d),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(fa('$d'),style:TextStyle(color:holiday?Colors.red:null,fontWeight:selected==d?FontWeight.bold:null)),Row(mainAxisAlignment:MainAxisAlignment.center,children:[if(hasOcc)const Icon(Icons.circle,size:5,color:Colors.orange),if(hasTask)const Icon(Icons.circle,size:5,color:Colors.blue)])]));}),const Divider(),Expanded(child:ListView(children:[...rules.map((o)=>ListTile(leading:Icon(o.isHoliday?Icons.event_busy:Icons.event,color:o.isHoliday?Colors.red:null),title:Text(o.title),trailing:TextButton(onPressed:()=>widget.onReminder(o),child:const Text('یادآوری بساز')))),...tasks.map((t)=>ListTile(leading:const Icon(Icons.task_alt),title:Text(t.title),subtitle:Text('${fa(two(t.due.hour))}:${fa(two(t.due.minute))}'))),if(rules.isEmpty&&tasks.isEmpty)const ListTile(title:Text('موردی برای این روز ثبت نشده'))]))]);}}
